package com.sakti.banking.entity;
import jakarta.persistence.*; import java.time.*;
@Entity @Table(name="beneficiaries",uniqueConstraints=@UniqueConstraint(name="uk_beneficiary_owner_account",columnNames={"owner_id","accountNumber"}))
public class Beneficiary { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="owner_id") private AppUser owner; @Column(nullable=false,length=100) private String name; @Column(nullable=false,length=20) private String accountNumber; @Column(length=20) private String bankCode; private boolean enabled=true; private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();}
 public Long getId(){return id;} public AppUser getOwner(){return owner;} public void setOwner(AppUser v){owner=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getAccountNumber(){return accountNumber;} public void setAccountNumber(String v){accountNumber=v;} public String getBankCode(){return bankCode;} public void setBankCode(String v){bankCode=v;} public boolean isEnabled(){return enabled;} public void setEnabled(boolean v){enabled=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
